/**
 * PTU (Provisioned Throughput) Calculator — Together AI
 *
 * Attribute-driven, drop-in for Webflow. Build the markup in Designer with the
 * `data-ptu="…"` hooks (see the HTML template / attribute reference), then load
 * this page script via:  window.loadPageScript('ptu-calculator.js')
 *
 * ─────────────────────────────────────────────────────────────────────────
 *  EDIT ME — everything tunable lives in the CONFIG block right below.
 *    • MODELS  — per-model capacity, hourly rate, token ratios.
 *                Add a model = add one entry; the dropdown fills itself.
 *    • TERMS   — commitment terms, discounts, and the pill badge text.
 *    • DEFAULTS / HOURS_PER_MONTH — starting selections + month length.
 *  NOTE: this is a client-side calculator, so every number here is public in
 *  the shipped JS. Confirm the discount/rate values before launch.
 * ─────────────────────────────────────────────────────────────────────────
 */
(function ($) {
  'use strict';

  /* ======================= CONFIG — EDIT THESE ========================== */

  // Add a model: copy a block, change the key + numbers. Key is internal only.
  var MODELS = {
    'minimax-m2.7': {
      label: 'Minimax M2.7',
      ptuCapacity: 231000, // normalized TPM per PTU
      baseHourly: 1.0, // $ per PTU per hour
      ratioCached: 1, // multiplier — cached input tokens
      ratioInput: 5, // multiplier — non-cached input tokens
      ratioOutput: 30, // multiplier — output tokens
    },
    // 'next-model': { label: 'Model Name', ptuCapacity: 231000, baseHourly: 1.0, ratioCached: 1, ratioInput: 5, ratioOutput: 30 },
  };

  // Commitment terms. `discount` is a fraction (0.15 = 15% off list).
  // `badge` is the small label shown inside each pill.
  var TERMS = {
    '3mo': { discount: 0.0, badge: 'Min. required' },
    '12mo': { discount: 0.15, badge: '~15% off*' }, // PLACEHOLDER — confirm
  };

  var DEFAULTS = {
    model: 'minimax-m2.7',
    term: '3mo',
    cache: 30, // % cache hit rate the slider starts on
  };

  var HOURS_PER_MONTH = 730; // 365 × 24 / 12
  var ACTIVE_CLASS = 'is-active'; // toggled on the selected term pill
  var EMPTY_CLASS = 'is-empty'; // toggled on result values when there's no input

  /* ========================= END CONFIG ================================= */

  // `data-ptu="name"` selector helper.
  function sel(name) {
    return '[data-ptu="' + name + '"]';
  }

  // Compact currency: $1.23M / $45K / $1.2K / $12.34
  function fmtCost(value) {
    if (value >= 1000000) return '$' + (value / 1000000).toFixed(2) + 'M';
    if (value >= 10000) return '$' + Math.round(value / 1000) + 'K';
    if (value >= 1000) return '$' + (value / 1000).toFixed(1) + 'K';
    return '$' + value.toFixed(2);
  }

  function PTUCalc(root) {
    var $root = $(root);

    // Inputs
    var $modelSelect = $root.find(sel('model-select'));
    var $inputTPM = $root.find(sel('input-tpm'));
    var $outputTPM = $root.find(sel('output-tpm'));
    var $cacheRange = $root.find(sel('cache-rate'));
    var $cacheDisplay = $root.find(sel('cache-display'));
    var $termPills = $root.find('[data-ptu-term]');

    // Outputs
    var $ptuOut = $root.find(sel('result-ptu'));
    var $hourlyOut = $root.find(sel('result-hourly'));
    var $monthlyOut = $root.find(sel('result-monthly'));
    var $modelLabel = $root.find(sel('model-label'));
    var $modelNote = $root.find(sel('model-note'));

    var state = {
      model: MODELS[DEFAULTS.model] ? DEFAULTS.model : Object.keys(MODELS)[0],
      term: TERMS[DEFAULTS.term] ? DEFAULTS.term : Object.keys(TERMS)[0],
    };

    function model() {
      return MODELS[state.model];
    }

    // Fill the <select> from MODELS so the config is the single source of truth.
    function buildModelOptions() {
      if (!$modelSelect.length) return;
      $modelSelect.empty();
      Object.keys(MODELS).forEach(function (key) {
        $modelSelect.append($('<option>').val(key).text(MODELS[key].label));
      });
      $modelSelect.val(state.model);
    }

    // Fill each pill's badge from TERMS (only where a [data-ptu="term-badge"] exists).
    function buildTermBadges() {
      $termPills.each(function () {
        var key = $(this).attr('data-ptu-term');
        var badge = TERMS[key] && TERMS[key].badge;
        if (badge != null) $(this).find(sel('term-badge')).text(badge);
      });
    }

    function setModel(key) {
      if (!MODELS[key]) return;
      state.model = key;
      renderModelInfo();
      calculate();
    }

    function setTerm(key) {
      if (!TERMS[key]) return;
      state.term = key;
      $termPills.each(function () {
        var active = $(this).attr('data-ptu-term') === key;
        $(this)
          .toggleClass(ACTIVE_CLASS, active)
          .attr('aria-pressed', String(active));
      });
      calculate();
    }

    function renderModelInfo() {
      var m = model();
      $modelLabel.text(m.label);
      if (!$modelNote.length) return;
      var cachedK = Math.round(m.ptuCapacity / 1000);
      $modelNote.html(
        cachedK + 'K cached TPM/PTU &nbsp;·&nbsp; $' + m.baseHourly.toFixed(2) + '/PTU/hr<br>' +
          'Output = ' + m.ratioOutput + '× &nbsp;·&nbsp; ' +
          'Input = ' + m.ratioInput + '× &nbsp;·&nbsp; ' +
          'Cached = ' + m.ratioCached + '×'
      );
    }

    function updateCacheFill() {
      var v = $cacheRange.val();
      $cacheRange.css('--fill', v + '%'); // drives the orange track gradient
      $cacheDisplay.text(v + '%');
    }

    function calculate() {
      var m = model();
      var inputTPM = Math.max(0, parseFloat($inputTPM.val()) || 0);
      var outputTPM = Math.max(0, parseFloat($outputTPM.val()) || 0);
      var cacheRate = (parseFloat($cacheRange.val()) || 0) / 100;

      var cachedInput = inputTPM * cacheRate;
      var nonCachedInput = inputTPM * (1 - cacheRate);

      var normalizedTPM =
        cachedInput * m.ratioCached +
        nonCachedInput * m.ratioInput +
        outputTPM * m.ratioOutput;

      var ptus = normalizedTPM > 0 ? Math.ceil(normalizedTPM / m.ptuCapacity) : 0;

      var discount = (TERMS[state.term] && TERMS[state.term].discount) || 0;
      var rate = m.baseHourly * (1 - discount);
      var hourly = ptus * rate;
      var monthly = hourly * HOURS_PER_MONTH;

      render(ptus, hourly, monthly, inputTPM + outputTPM > 0);
    }

    function render(ptus, hourly, monthly, hasInput) {
      if (!hasInput) {
        $ptuOut.text('—').addClass(EMPTY_CLASS);
        $hourlyOut.text('—').addClass(EMPTY_CLASS);
        $monthlyOut.text('—').addClass(EMPTY_CLASS);
        return;
      }
      $ptuOut.text(ptus.toLocaleString()).removeClass(EMPTY_CLASS);
      $hourlyOut.text(fmtCost(hourly)).removeClass(EMPTY_CLASS);
      $monthlyOut.text(fmtCost(monthly)).removeClass(EMPTY_CLASS);
    }

    function bind() {
      $modelSelect.on('change', function () {
        setModel($(this).val());
      });
      $inputTPM.on('input', calculate);
      $outputTPM.on('input', calculate);
      $cacheRange.on('input', function () {
        updateCacheFill();
        calculate();
      });
      $termPills.on('click', function (e) {
        e.preventDefault();
        setTerm($(this).attr('data-ptu-term'));
      });
    }

    // Boot
    buildModelOptions();
    buildTermBadges();
    if ($cacheRange.length && DEFAULTS.cache != null) $cacheRange.val(DEFAULTS.cache);
    bind();
    renderModelInfo();
    updateCacheFill();
    setTerm(state.term); // sets the active pill + runs the first calculate()
  }

  $(function () {
    $(sel('calc')).each(function () {
      PTUCalc(this);
    });
  });
})(window.jQuery);
